public final class PriceTicker {
    private final PropertyChangeSupport pcs = new PropertyChangeSupport(this);
    public void addPriceListener(PropertyChangeListener l) {
        pcs.addPropertyChangeListener("price", l);
    }
    private double price;
    public void setPrice(double next) {
        double old = price;
        price = next;
        pcs.firePropertyChange("price", old, next);   // old.equals(next) => no event
    }
}

